before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <set>
int main() {
    std::set<int> badges{3, 1, 3};
    auto result = badges.insert(3);
    std::cout << result.second << " " << badges.size() << "\n";
    for (int badge : badges) std::cout << badge << " ";
    std::cout << "\n";
}
```

